# The issue is that the backtracking only checks edges involving the current vertex
# but doesn't check edges between two already-assigned vertices that might have
# been assigned in a different order. Let me fix this.

import random

# Edges
edges = []
for g in range(3):
    for i in range(3):
        for j in range(i+1, 3):
            edges.append((g*3 + i, g*3 + j))
for g in range(2):
    for i in range(3):
        edges.append((g*3 + i, (g+1)*3 + i))

def solve_with_restarts():
    for attempt in range(5000):
        labels = [None] * 9
        used_labels = set()
        used_diffs = set()

        # Randomize vertex order
        order = list(range(9))
        random.shuffle(order)

        def backtrack(idx):
            if idx == 9:
                # Verify all edges
                diffs = []
                for (u, v) in edges:
                    diffs.append(abs(labels[u] - labels[v]))
                if len(set(diffs)) == 15:
                    return labels[:]
                return None

            v = order[idx]

            # Try labels in random order
            available = [l for l in range(16) if l not in used_labels]
            random.shuffle(available)

            for label in available:
                labels[v] = label
                used_labels.add(label)

                # Check edge differences for edges involving v
                valid = True
                new_diffs = []
                for (u, w) in edges:
                    if u == v or w == v:
                        other = w if u == v else u
                        if labels[other] is not None:
                            diff = abs(labels[u] - labels[w])
                            if diff in used_diffs:
                                valid = False
                                break
                            new_diffs.append(diff)

                if valid:
                    for d in new_diffs:
                        used_diffs.add(d)

                    result = backtrack(idx + 1)
                    if result is not None:
                        return result

                    for d in new_diffs:
                        used_diffs.discard(d)

                labels[v] = None
                used_labels.discard(label)

            return None

        result = backtrack(0)
        if result is not None:
            return result

    return None

result = solve_with_restarts()
if result:
    print("Solution found:", result)
    diffs = []
    for (u, v) in edges:
        diffs.append(abs(result[u] - result[v]))
    print("Edge differences:", sorted(diffs))
    print("All distinct:", len(set(diffs)) == 15)
else:
    print("No solution found")
